// Extract the CV data sent by ReviZoR
const body = $input.first().json.body || $input.first().json;

const jobId      = body.job_id;
const sessionId  = body.session_id;
const callbackUrl = body.callback_url;
const origCv     = body.original_cv  || {};
const optCv      = body.optimized_cv || {};
const origText   = body.original_text  || '';
const optText    = body.optimized_text || '';

// Basic diff: find sections that changed
const changes = [];
const sections = ['name','title','email','phone','location','summary'];
for (const key of sections) {
  if (JSON.stringify(origCv[key]) !== JSON.stringify(optCv[key])) {
    changes.push(key);
  }
}
if ((origCv.experience || []).length !== (optCv.experience || []).length) {
  changes.push('experience (count changed)');
}
if ((origCv.skills?.categories || []).length !== (optCv.skills?.categories || []).length) {
  changes.push('skills');
}

// You can add your own verification logic here.
// For example: check that the name wasn't changed, that bullets are action-verbs,
// that dates are consistently formatted, etc.

// By default: pass the optimized CV through as reviewed (no changes).
// Replace `reviewedCv` with your corrected version if you modify anything.
const reviewedCv = optCv;   // <-- swap this with your corrected CV dict
const changesSummary = changes.length
  ? `Sections changed by AI: ${changes.join(', ')}`
  : 'No structural changes detected.';

return [{
  json: {
    job_id:          jobId,
    session_id:      sessionId,
    callback_url:    callbackUrl,
    reviewed_cv:     reviewedCv,
    changes_summary: changesSummary,
    status:          'completed',
    error:           null,
  }
}];

// Sign the callback body with the shared secret
// Set N8N_CALLBACK_SECRET in n8n's environment variables (Settings → Variables)
const secret = $env.N8N_CALLBACK_SECRET || '';
const item = $input.first().json;

if (!secret) {
  // No secret configured — skip signing
  return [{ json: { ...item, signature: '' } }];
}

// HMAC-SHA256 using the Web Crypto API (available in n8n Code nodes)
const body = JSON.stringify({
  job_id:          item.job_id,
  session_id:      item.session_id,
  status:          item.status,
  reviewed_cv:     item.reviewed_cv,
  changes_summary: item.changes_summary,
  error:           item.error,
});

const encoder = new TextEncoder();
const keyData = encoder.encode(secret);
const msgData = encoder.encode(body);

const cryptoKey = await crypto.subtle.importKey(
  'raw', keyData, { name: 'HMAC', hash: 'SHA-256' }, false, ['sign']
);
const sigBuffer = await crypto.subtle.sign('HMAC', cryptoKey, msgData);
const sigHex = Array.from(new Uint8Array(sigBuffer))
  .map(b => b.toString(16).padStart(2, '0'))
  .join('');

return [{ json: { ...item, signature: sigHex } }];
